 boolean handleDialogKey(AlertDialog host,String titleValue,int key,KeyEvent event){
  if(event.getAction()!=KeyEvent.ACTION_DOWN)return controllerKey(key)||key==KeyEvent.KEYCODE_BACK;
  if(key==KeyEvent.KEYCODE_BACK||key==KeyEvent.KEYCODE_BUTTON_B){if(titleValue.equals("应用选择")||titleValue.equals("覆盖资料"))showSelectionOptions();else{if(titleValue.equals("调整选择"))finishSelection();host.cancel();}return true;}
  if(directionKey(key)){moveFocus(host.getWindow().getDecorView(),host.getCurrentFocus(),focusDelta(key));return true;}
  if(key==KeyEvent.KEYCODE_BUTTON_A){View focused=host.getCurrentFocus();if(focused!=null&&focused.isEnabled()&&focused.isClickable())focused.performClick();return true;}
  return false;
 }
