 void generateAuthorization(){if(!Environment.isExternalStorageManager())return;if(authorizationPassed()){new File(SetupEngine.HOME,"KPA_Authorize.sh").delete();return;}try{SetupEngine.mkdir(authorizationReceipt().getParentFile());String path=RootBridge.q(authorizationReceipt().getAbsolutePath()),authDir=RootBridge.q(authorizationReceipt().getParentFile().getAbsolutePath());String script="#!/system/bin/sh\nif [ \"$(id -u)\" != 0 ]; then echo 'ERROR: Root permission missing.'; exit 1; fi\nmkdir -p "+authDir+"\nif ! cmd appops set --uid "+getPackageName()+" MANAGE_EXTERNAL_STORAGE allow; then echo 'ERROR: Storage permission grant failed.'; exit 1; fi\nif ! printf '%s\\n' "+RootBridge.q(authorizationToken)+" > "+path+" || [ \"$(cat "+path+")\" != "+RootBridge.q(authorizationToken)+" ]; then echo 'ERROR: Authorization receipt verification failed.'; exit 1; fi\necho 'SUCCESS: Storage Root authorized.'\n";SetupEngine.write(new File(SetupEngine.HOME,"KPA_Authorize.sh"),script);}catch(Exception e){toast("授权脚本生成失败："+e.getMessage());}} void confirmExecution(){if(!authorizationPassed()){step=0;save();render();toast("先执行存储 Root 授权脚本");return;}dialogBuilder().setTitle("最终确认执行").setMessage(applicationSelection()+" 清理旧配置 · 覆盖资料 · 不备份"+(skipGbaExpected?" · GBA 自行覆盖":"")).setNegativeButton("取消",null).setPositiveButton("确认开始",(d,w)->{finalized=false;progress=0;preciseProgress=0;itemDone=0;itemTotal=0;progressPhase="";displayedLogTimes.clear();getPreferences(0).edit().putInt("progress",0).putBoolean("executionConfirmed",true).remove("executionError").putString("lastLog",chineseLog("用户已确认，开始检查执行条件")).apply();task(()->{prepareBatch();executeBatch();});}).show();}
 void autoDiscover(){if(!Environment.isExternalStorageManager()||discoveryRunning||discovered||busy)return;if(config!=null&&!config.isDirectory())config=null;if(gba!=null&&(!gba.isFile()||!gba.canRead()))gba=null;discoveryRunning=true;render();executor.execute(()->{ArrayList<File> configs=new ArrayList<>(),games=new ArrayList<>();boolean gbaSkipped=getPreferences(0).getBoolean("gbaSkipped",false);if(config==null||gba==null&&!gbaSkipped){StorageManager sm=(StorageManager)getSystemService(STORAGE_SERVICE);for(StorageVolume v:sm.getStorageVolumes())if(v.getDirectory()!=null)discoverTree(v.getDirectory(),0,configs,games);}String report="";try{if(config==null||!config.isDirectory()){if(configs.size()==1){config=configs.get(0);scanApps();sources.discover(config);}else report=configs.isEmpty()?"未找到资料目录，请手动选择":"发现多个资料目录，请手动确认";}if(!gbaSkipped&&(gba==null||!gba.isFile())){if(games.size()==1)gba=games.get(0);else if(games.size()>1)report+="\n发现多个 GBA整包，请手动确认";}if(report.trim().isEmpty()||report.trim().startsWith("发现多个 GBA")){if(sources.mainZip==null||!sources.mainZip.isFile()||sources.androidZip==null||!sources.androidZip.isFile()){File main=sources.mainZip,android=sources.androidZip,lists=sources.lists;sources.discover(config);if(main!=null&&main.isFile())sources.mainZip=main;if(android!=null&&android.isFile())sources.androidZip=android;if(lists!=null&&lists.isDirectory())sources.lists=lists;}detectSelection();report="✓ 资料自动识别完成\n"+spaceReport+(skipGbaExpected?"\n空间不足：继续安装应用与覆盖配置，GBA 请自行覆盖":"");}}catch(Exception e){report="资料检测失败："+e.getMessage();}final String result=report;runOnUiThread(()->{selectionReport=result;discoveryRunning=false;discovered=true;save();render();});});}
 void discoverTree(File dir,int depth,List<File> configs,List<File> games){if(depth>4||dir.getName().equals("Android")||dir.getName().equals("KPA-Tools")||dir.getName().equals("PegasusG-Setup")||dir.getName().equals("Roms"))return;File[] files=dir.listFiles();if(files==null)return;for(File f:files){if(f.isDirectory()&&!f.getName().startsWith("."))discoverTree(f,depth+1,configs,games);else if(f.isFile()&&f.getName().toLowerCase(Locale.ROOT).endsWith(".zip")){int kind=SourceDiscovery.kind(f);if(kind==1){File root=SourceDiscovery.bundleRoot(f);if(!configs.contains(root))configs.add(root);}else if(kind==2&&!games.contains(f))games.add(f);}}}

