 void detectSelection()throws Exception {
  boolean preview=!getPreferences(0).getBoolean("executionConfirmed",false);if(preview)beginCheckLog();
  if(config==null||!config.isDirectory())throw new Exception("请选择完整资料文件夹");
  if(gba!=null&&(!gba.isFile()||SourceDiscovery.kind(gba)!=2))throw new Exception("所选 ZIP 内未识别到 GBA 游戏和列表结构");
  if(sources.mainZip==null||!sources.mainZip.isFile())throw new Exception("未找到定制主配置 ZIP，请在导入选项选择");
  if(SourceDiscovery.kind(sources.mainZip)!=1)throw new Exception("主配置缺少天马G或 RA 配置，请补选");
  if(sources.androidZip==null||!sources.androidZip.isFile()||SourceDiscovery.kind(sources.androidZip)!=3)throw new Exception("缺少有效安卓覆盖配置，请补选");
  for(AppSpec a:apps){if(a.install&&(a.apk==null||!a.apk.isFile()))throw new Exception("缺少 "+a.label+" 安装包");if(a.configure&&!a.installed&&!a.install)throw new Exception("请勾选安装 "+a.label+"，或取消导入配置");}
  if(gba!=null&&(!apps[0].configure||!apps[1].configure))throw new Exception("导入 GBA 必须选择天马G与 RA 的配置");long available=new android.os.StatFs(destination.getAbsolutePath()).getAvailableBytes();SetupEngine.SpaceEstimate quote=SetupEngine.estimateSpace(sources.mainZip,gba,sources,apps,destination);skipGbaExpected=gba!=null&&!quote.includes(available);spaceReport=storageName()+"可用 "+SetupEngine.gb(available)+" GiB · 预计解压 "+SetupEngine.gb(quote.full)+" GiB"+(gba==null?" · 未选GBA":"");recordCheck("空间检查："+spaceReport+"（仅导入文件，不计应用安装大小）",preview);auditConfigs(preview);runOnUiThread(()->selectionReport="✓ 必备资料与应用已确认");recordCheck(gba==null?"资料检测通过，本次跳过 GBA整包":"资料与应用检测通过",preview);
 }
