 interface Work {void run() throws Exception;}
 void task(Work w){if(busy)return;busy=true;if(step==2)showRunningOverlay();else render();
  wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"PegasusG:setup");wake.acquire(6*60*60*1000L);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON);monitor.removeCallbacks(heartbeat);monitor.post(heartbeat);
  executor.execute(()->{try{w.run();}catch(Throwable e){boolean execution=step==2&&getPreferences(0).getBoolean("executionConfirmed",false);if(execution)getPreferences(0).edit().putString("executionError",String.valueOf(e.getMessage())).apply();line("✕ "+e.getMessage());if(!execution)runOnUiThread(()->dialogBuilder().setTitle("步骤未完成").setMessage(e.getMessage()+"\n\n执行日志已保留，请检查失败原因。").setPositiveButton("知道了",null).show());}
   finally{runOnUiThread(()->{busy=false;clearExecutionProtection();getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_VISIBLE);rootShell=null;screen=null;render();});}});
 }
