 void chooseStorage(){StorageManager sm=(StorageManager)getSystemService(STORAGE_SERVICE);ArrayList<File> roots=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();roots.add(new File(SetupEngine.HOME));labels.add(SetupEngine.HOME);for(StorageVolume volume:sm.getStorageVolumes()){File root=volume.getDirectory();if(root==null||root.getAbsolutePath().equals(SetupEngine.HOME)||!root.isDirectory())continue;roots.add(root);labels.add(root.getAbsolutePath());}String[] choices=labels.toArray(new String[0]);largeDialog(dialogBuilder().setCustomTitle(dialogTitle("Roms存储")).setView(choiceView(choices,(d,w)->{if(w<0||w>=roots.size())return;File next=roots.get(w);markChoice("destination",destination,next);destination=next;invalidatePlan();save();render();autoDiscover();})).setNegativeButton("返回",(d,w)->returnToSources()));}
 void assignZip(String kind,File f){if(kind.equals("gba"))getPreferences(0).edit().putBoolean("gbaSkipped",false).apply();File previous=kind.equals("gba")?gba:kind.equals("main")?sources.mainZip:sources.androidZip;markChoice(kind,previous,f);if(kind.equals("gba"))gba=f;else if(kind.equals("main"))sources.mainZip=f;else if(kind.equals("android"))sources.androidZip=f;}
