 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=51||result!=RESULT_OK||data==null||data.getData()==null)return;
  pendingKind=getPreferences(0).getString("pendingKind","gba");
  Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}
  String display="GBA整合包.zip";try(Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())display=cursor.getString(0);}catch(Exception ignored){}
  if(display==null||!display.toLowerCase(Locale.ROOT).endsWith(".zip")){toast("请选择对应的 .zip 文件");return;}
  File direct=localDocument(uri);if(direct!=null&&direct.isFile()&&direct.canRead()){assignZip(pendingKind,direct);invalidatePlan();save();render();return;}
  final String name=display;task(()->{line("正在读取所选 ZIP 文件，请稍候…");File imports=getExternalFilesDir("imports");if(imports==null)imports=new File(getFilesDir(),"imports");SetupEngine.mkdir(imports);File target=new File(imports,System.currentTimeMillis()+"-"+name.replaceAll("[\\\\/:*?\"<>|\\r\\n]","_"));
   try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(target)){if(in==null)throw new IOException("无法读取所选文件");SetupEngine.copy(in,out);}try(java.util.zip.ZipFile z=SetupEngine.openZip(target)){if(z.size()==0)throw new IOException("所选 ZIP 是空文件");}
   assignZip(pendingKind,target);invalidatePlan();save();line("✓ 已选择："+name);
  });
 }
 File localDocument(Uri uri){try{if("file".equals(uri.getScheme()))return new File(uri.getPath());if(DocumentsContract.isDocumentUri(this,uri)){String id=DocumentsContract.getDocumentId(uri);if(id.startsWith("raw:"))return new File(id.substring(4));if(uri.getAuthority().equals("com.android.externalstorage.documents")){int colon=id.indexOf(':');if(colon>=0){String volume=id.substring(0,colon);return new File(volume.equals("primary")?SetupEngine.HOME:"/storage/"+volume,id.substring(colon+1));}}}}catch(Exception ignored){}return null;}
 void pick(boolean folder,Chosen callback){
  if(!Environment.isExternalStorageManager()){storagePermission();return;}
  List<File> roots=new ArrayList<>();StorageManager sm=(StorageManager)getSystemService(STORAGE_SERVICE);
  for(StorageVolume v:sm.getStorageVolumes())if(v.getDirectory()!=null)roots.add(v.getDirectory());
  if(roots.isEmpty())roots.add(new File(SetupEngine.HOME));String[] labels=new String[roots.size()];for(int i=0;i<labels.length;i++)labels[i]=roots.get(i).getAbsolutePath();
  largeDialog(dialogBuilder().setCustomTitle(dialogTitle(folder?"选择文件夹":"选择 ZIP")).setView(choiceView(labels,(d,w)->browse(roots.get(w),roots.get(w),folder,callback,null))).setNegativeButton("返回",(d,w)->returnToSources()));
 }
 void markFreshInstall(){try{PackageInfo info=getPackageManager().getPackageInfo(getPackageName(),0);long stamp=info.lastUpdateTime,build=info.getLongVersionCode();android.content.SharedPreferences p=getPreferences(0);if(p.getLong("installStamp",-1)!=stamp||p.getLong("installBuild",-1)!=build)p.edit().putLong("installStamp",stamp).putLong("installBuild",build).putBoolean("cleanupPending",true).apply();}catch(Exception ignored){}}
 void cleanPreviousInstall(){if(!Environment.isExternalStorageManager()||!getPreferences(0).getBoolean("cleanupPending",false))return;File root=new File(SetupEngine.HOME);File[] files=root.listFiles();if(files!=null)for(File f:files)if(f.isFile()&&(f.getName().equals("KPA_Authorize.sh")||f.getName().startsWith("KPA_Setup_")&&f.getName().endsWith(".sh")))f.delete();getPreferences(0).edit().putBoolean("cleanupPending",false).apply();}
 void browse(File root,File dir,boolean folder,Chosen callback,File selected){
  File[] all=dir.listFiles(f->!f.getName().startsWith(".")&&(f.isDirectory()||!folder&&f.getName().toLowerCase(Locale.ROOT).endsWith(".zip")));
  if(all==null){toast("目录无权限或不可读取");return;}
  Arrays.sort(all,Comparator.<File,Boolean>comparing(f->!f.isDirectory()).thenComparing(File::getName));
  LinearLayout list=new LinearLayout(this);list.setOrientation(1);list.setPadding(dp(12),dp(8),dp(12),dp(8));
  if(folder)addBrowserRow(list,"当前文件夹",dir,true,dir.equals(selected),root,dir,folder,callback);
  if(!dir.equals(root))addBrowserRow(list,"↑ 返回上级",dir.getParentFile(),false,false,root,dir,folder,callback);
  for(File f:all)addBrowserRow(list,f.isDirectory()?"▸ "+f.getName():f.getName(),f,folder||!f.isDirectory(),f.equals(selected),root,dir,folder,callback);
  ScrollView scroll=new ScrollView(this);scroll.setVerticalScrollBarEnabled(false);scroll.setBackgroundColor(bg);scroll.addView(list);scroll.setTag(Integer.valueOf(Math.max(3,list.getChildCount())));
  AlertDialog.Builder builder=dialogBuilder().setCustomTitle(dialogTitle(dir.getAbsolutePath())).setView(scroll).setNegativeButton("返回",(d,w)->returnToSources());
  if(selected!=null)builder.setPositiveButton("确定",(d,w)->callback.accept(selected));
  largeDialog(builder);
 }
 void addBrowserRow(LinearLayout list,String label,File file,boolean selectable,boolean checked,File root,File dir,boolean folder,Chosen callback){
  LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(18),0,dp(12),0);row.setBackground(shape(checked?KpaTheme.RUNNING_SURFACE:panel));TextView name=text(label,KpaLayout.ITEM_TEXT,checked?runningColor:fg);name.setGravity(Gravity.CENTER_VERTICAL);name.setPadding(0,0,0,0);row.addView(name,new LinearLayout.LayoutParams(0,dp(50),1));
  if(selectable){RadioButton radio=new RadioButton(this);radio.setChecked(checked);radio.setButtonTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{success,muted}));row.addView(radio,new LinearLayout.LayoutParams(dp(50),dp(50)));radio.setOnClickListener(v->replaceBrowse(v,()->browse(root,dir,folder,callback,file)));}
  LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(KpaLayout.BROWSER_ROW));lp.setMargins(0,dp(3),0,dp(3));list.addView(row,lp);focusable(row);row.setOnClickListener(v->{if(file.isDirectory()&&!label.equals("当前文件夹")&&!label.startsWith("↑"))replaceBrowse(v,()->browse(root,file,folder,callback,null));else if(label.startsWith("↑"))replaceBrowse(v,()->browse(root,file,folder,callback,null));else if(selectable)replaceBrowse(v,()->browse(root,dir,folder,callback,file));});
 }
 void replaceBrowse(View source,Runnable next){int y=0;View parent=source;while(parent!=null&&!(parent instanceof ScrollView)){android.view.ViewParent p=parent.getParent();parent=p instanceof View?(View)p:null;}if(parent instanceof ScrollView)y=((ScrollView)parent).getScrollY();final int restore=y;AlertDialog old=currentDialog;changeDialog(old,next);monitor.post(()->{AlertDialog now=currentDialog;if(now==null)return;View custom=now.getWindow().getDecorView().findViewWithTag("kpaDialog");ScrollView scroll=findScroll(custom);if(scroll!=null)scroll.scrollTo(0,restore);});}
 ScrollView findScroll(View view){if(view instanceof ScrollView)return (ScrollView)view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){ScrollView found=findScroll(group.getChildAt(i));if(found!=null)return found;}}return null;}
 void scanApps(){
  List<File> archiveFiles=new ArrayList<>();SourceDiscovery.files(config,0,archiveFiles);File[] apks=archiveFiles.stream().filter(f->f.getName().toLowerCase(Locale.ROOT).endsWith(".apk")).toArray(File[]::new);
  for(AppSpec a:apps){a.apk=null;try{getPackageManager().getPackageInfo(a.pkg,0);a.installed=true;}catch(Exception e){a.installed=false;}}
  if(apks!=null){Arrays.sort(apks,Comparator.comparing(File::getName));for(File f:apks){PackageInfo pi=getPackageManager().getPackageArchiveInfo(f.getAbsolutePath(),0);if(pi!=null)for(AppSpec a:apps)if(a.pkg.equals(pi.packageName)){PackageInfo previous=a.apk==null?null:getPackageManager().getPackageArchiveInfo(a.apk.getAbsolutePath(),0);if(previous==null||pi.getLongVersionCode()>previous.getLongVersionCode())a.apk=f;}}}
  for(AppSpec a:apps){String manual=getPreferences(0).getString("apk."+a.pkg,"");if(!manual.isEmpty()){File f=new File(manual);PackageInfo info=f.isFile()?getPackageManager().getPackageArchiveInfo(f.getAbsolutePath(),0):null;if(info!=null&&a.pkg.equals(info.packageName))a.apk=f;}}
  for(AppSpec a:apps){a.configure=defaultConfigure(a);a.install=defaultInstall(a);}
 }
