 void auditConfigs(boolean preview)throws Exception {Map<String,String> report=ConfigAudit.inspect(this,config,apps);initialStates.clear();initialStates.putAll(report);for(AppSpec app:apps)if(report.containsKey(app.pkg))recordCheck(app.label+"："+report.get(app.pkg),preview);}

 boolean scriptDone(){try{return run!=null&&SetupEngine.read(new File(run,SetupEngine.STATUS)).trim().equals("DONE");}catch(Exception e){return false;}}
 boolean permissionPassed(String pkg){return verifiedPermissions.containsKey(pkg)?Boolean.TRUE.equals(verifiedPermissions.get(pkg)):getPreferences(0).getBoolean(pkg+".verifiedPermission",false);}
 void collectPermissions(RootBridge rb)throws Exception {int yes=0,total=0;for(AppSpec a:apps)if(a.configure){total++;boolean passed=true;try{PackageInfo pi=getPackageManager().getPackageInfo(a.pkg,PackageManager.GET_PERMISSIONS);if(pi.requestedPermissions!=null)for(int i=0;i<pi.requestedPermissions.length;i++){String p=pi.requestedPermissions[i];if(p.equals("android.permission.MANAGE_EXTERNAL_STORAGE")){if(rb==null||!rb.call("cmd appops get "+RootBridge.q(a.pkg)+" MANAGE_EXTERNAL_STORAGE").contains("allow"))passed=false;}else if(p.equals("android.permission.READ_EXTERNAL_STORAGE")||p.equals("android.permission.WRITE_EXTERNAL_STORAGE")){if((pi.requestedPermissionsFlags[i]&PackageInfo.REQUESTED_PERMISSION_GRANTED)==0)passed=false;}}}catch(Exception e){passed=false;}verifiedPermissions.put(a.pkg,passed);getPreferences(0).edit().putBoolean(a.pkg+".verifiedPermission",passed).apply();if(passed)yes++;}final int y=yes,t=total;runOnUiThread(()->summaryReport="系统存储权限："+y+" / "+t+" 款已通过。应用内目录、BIOS与手柄请按设置教程确认。");}
 void readRootResult()throws Exception {
  if(run==null)throw new Exception("请先一键检测，生成本批次脚本");File state=new File(run,SetupEngine.STATUS);if(!state.isFile()){line("初始化尚未执行。请执行初始化，或在掌机管理 → 设备 → Root脚本运行本批次脚本。");return;}
  String s=SetupEngine.read(state).trim();if(s.equals("DONE")){if(!initialPassed())throw new Exception("本批次缺少完整的文件存在核验记录，请重新准备");finishBatch();finalized=true;runOnUiThread(()->{updateProgress(100);save();});}
  else if(s.equals("ERROR"))throw new Exception("初始化中断，请查看本批次执行日志.txt；不会创建备份");else line("当前阶段："+s+"。脚本仍在执行，请稍后再检测。");
 }
 void finishBatch()throws Exception {RootBridge rb=null;try{rb=new RootBridge(this);rb.check();}catch(Exception ignored){rb=null;}collectPermissions(rb);new File(SetupEngine.HOME,"KPA_Authorize.sh").delete();line("✓ 初次安装与覆盖已核验，请在最后一页查看手动设置教程。");}
 void launch(String pkg){try{Intent i=getPackageManager().getLaunchIntentForPackage(pkg);if(i==null){toast("应用未安装或没有启动入口");return;}startActivity(i);}catch(Exception e){toast(e.getMessage());}}
 void verify()throws Exception {
  if(run==null||!scriptDone())throw new Exception("请先完成本批次初始化脚本");RootBridge rb=null;try{rb=new RootBridge(this);rb.check();}catch(Exception ignored){rb=null;}
  if(rb==null){File entry=IntegrityVerifier.exportEntry(run);line("本次复核需通过掌机助手的 Root脚本入口执行："+entry);runOnUiThread(()->showScript(entry,"检查所有目标文件是否存在。不会启动应用或修改配置。"));return;}
  rb.call("sh "+RootBridge.q(new File(run,SetupEngine.VERIFY_SCRIPT).getAbsolutePath()));collectPermissions(rb);
  if(IntegrityVerifier.passed(run)){finishBatch();line("✓ 本次文件存在复核通过："+IntegrityVerifier.count(run)+" 个目标文件。");}
  else{String details=new File(run,SetupEngine.DETAILS).isFile()?SetupEngine.read(new File(run,SetupEngine.DETAILS)):"无详细记录";StringBuilder errors=new StringBuilder();int n=0;for(String l:details.split("\n"))if(!l.endsWith(": OK")&&n++<30)errors.append(l).append('\n');line("本次文件存在复核未通过。初次覆盖通过记录仍保留。\n"+errors);runOnUiThread(()->summaryReport="本次复核发现文件或目录异常，请查看操作记录。初次覆盖通过记录保留。");}
 }
 static boolean needsDirectory(String p){return p.equals("com.dsemu.drastic")||p.equals("xyz.aethersx2.android")||p.equals("org.pegasus_frontend.android")||p.equals("org.dolphinemu.mmjr")||p.equals("org.citra.emu");}
 static String requirements(String p){
  if(p.equals("org.pegasus_frontend.android"))return "允许存储 / 所有文件访问。重新加载媒体缓存；使用 NDS 等模拟器时，在“可访问的安卓目录”添加对应游戏文件夹。";
  if(p.equals("com.retroarch.aarch64"))return "允许存储 / 所有文件访问。核心、界面资源和初始化版本已提前导入，不需要再等待首次解包；手柄模式仍应在系统中设置为 Xbox、日式 ABXY。";
  if(p.equals("com.dsemu.drastic"))return "选择外置数据目录：内存/DraStic，确认“使用此文件夹”。按游戏需要授予麦克风权限。";
  if(p.equals("xyz.aethersx2.android"))return "若出现首次引导，按默认选项完成。添加实际 PS2 游戏目录；确认 BIOS 和控制器映射。已有公开配置导入不等于系统目录授权已完成。";
  if(p.equals("org.dolphinemu.mmjr"))return "允许存储权限；若提示选择数据目录，使用内存/mmjr2-vbi，并添加游戏目录。";
  if(p.equals("org.citra.emu"))return "允许存储权限；如需目录授权，选择内存/citra-emu 和实际 3DS 游戏目录。";
  return "允许应用申请的存储权限，确认游戏目录可读取。";
 }
 void save(){android.content.SharedPreferences.Editor e=getPreferences(0).edit().putString("config",config==null?"":config.getAbsolutePath()).putString("gba",gba==null?"":gba.getAbsolutePath()).putString("destination",destination.getAbsolutePath()).putInt("step",step).putInt("progress",progress).putString("mainZip",sources.mainZip==null?"":sources.mainZip.getAbsolutePath()).putString("androidZip",sources.androidZip==null?"":sources.androidZip.getAbsolutePath()).putString("lists",sources.lists==null?"":sources.lists.getAbsolutePath()).putBoolean("grantStorage",sources.grantStorage).putString("run",run==null?"":run.getAbsolutePath());for(AppSpec a:apps)e.putBoolean(a.pkg+".install",a.install).putBoolean(a.pkg+".configure",a.configure).putBoolean(a.pkg+".directory",Boolean.TRUE.equals(manualDirectory.get(a.pkg)));e.apply();}
 void restore(){android.content.SharedPreferences p=getPreferences(0);String cfg=p.getString("config",""),g=p.getString("gba",""),r=p.getString("run","");if(!cfg.isEmpty())config=new File(cfg);if(!g.isEmpty()&&!p.getBoolean("gbaSkipped",false))gba=new File(g);destination=new File(p.getString("destination",SetupEngine.HOME));if(!r.isEmpty())run=new File(r);if(run!=null&&!new File(run,SetupEngine.SCRIPT_PATH).isFile()&&!new File(run,SetupEngine.STATUS).isFile()){run=null;p.edit().putString("resumeRun",r).putString("run", "").putString("executionError","准备过程已中断，请重新确认执行").apply();}scanApps();for(AppSpec a:apps){a.install=p.getBoolean(a.pkg+".install",a.install);a.configure=p.getBoolean(a.pkg+".configure",a.configure);manualDirectory.put(a.pkg,p.getBoolean(a.pkg+".directory",false));}sources.discover(config==null?new File("/invalid"):config);sources.mainZip=storedFile(p,"mainZip",sources.mainZip);sources.androidZip=storedFile(p,"androidZip",sources.androidZip);sources.lists=storedFile(p,"lists",sources.lists);sources.grantStorage=p.getBoolean("grantStorage",true);progress=p.getInt("progress",0);step=Math.max(0,Math.min(p.getInt("step",0),3));}

 File storedFile(android.content.SharedPreferences p,String key,File fallback){if(!p.contains(key))return fallback;String path=p.getString(key,"");return path.isEmpty()?null:new File(path);}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 @Override public void onBackPressed(){if(interactionLocked()){toast("正在初始化，请等待当前步骤完成");return;}if(step>0){int target=step-1;if(target==2&&!selectionReport.startsWith("✓")&&run==null)target=1;if(!Environment.isExternalStorageManager()||!authorizationPassed())target=0;switchStep(target-step);}else super.onBackPressed();}
 @Override protected void onResume(){super.onResume();if(rootGuideActive)stopRootPageGuide();monitor.removeCallbacksAndMessages(null);if(!interactionLocked())clearExecutionProtection();if(!Environment.isExternalStorageManager()){if(!permissionPrompted){permissionPrompted=true;storagePermission();}}else{permissionPrompted=false;cleanPreviousInstall();generateAuthorization();}if(step==2&&executionRunning()&&!scriptDone()){getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);render();monitorRunningOverlay();return;}if(content!=null&&!busy){if(step==2&&scriptDone()&&initialPassed()&&!finalized){finalized=true;progress=100;task(this::finishBatch);}else render();}if(step==1)autoDiscover();autoRootCheck(false);if(step==0)monitorAuthorization();else if(step==2)monitorExecution();}
 @Override public void onWindowFocusChanged(boolean hasFocus){super.onWindowFocusChanged(hasFocus);if(!hasFocus)releaseControllerFocus();}
 @Override protected void onUserLeaveHint(){releaseControllerFocus();super.onUserLeaveHint();}
 @Override protected void onPause(){releaseControllerFocus();if(!interactionLocked()){getWindow().clearFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_VISIBLE);monitor.removeCallbacksAndMessages(null);}super.onPause();}
 @Override protected void onDestroy(){monitor.removeCallbacksAndMessages(null);stopRootPageGuide();clearExecutionProtection();getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);super.onDestroy();}

